tags.gen_ai.input.messages:
[
  {
    "role": "user",
    "parts": [
      {
        "type": "text",
        "content": "Beginne jetzt mit plan-only Clarification Planning.\n\nDu bekommst ausschliesslich offene Requirements, die nach HumanReview als Klaerungs- oder\nBreakdown-Arbeit weitergefuehrt werden sollen. Erkunde sie mit deinen Tools.\n\nErzeuge einen ClarificationPlan. Plane keine echten GitHub-Schreiboperationen. Pruefe deinen\nPlan mit check_clarification_plan und speichere genau einmal mit save_clarification_plan."
      }
    ]
  }
]
